/**
 * The Atelier CMS mark (DECISIONS 0495): the slanted cinnabar stripe with the
 * Newsreader A knocked in, framed by two viewfinder corners. Master: umbrella
 * brand/masters/atelier-mark-32-color-{light,dark}.svg (the 32 px cut, used at
 * chrome and welcome sizes); this inline copy is the shipped export.
 * The stripe is the mark's own pigment (--ain-mark-pigment, cinnabar): in the
 * app cinnabar lives here and nowhere else (0501). The corners follow the
 * theme (--ain-mark-ring: ink on paper, white on night); the A is a white
 * knock-out in both modes, as in the master.
 */
export const AtelierMark = (p: IconProps) => (
  <svg viewBox="-9 -9 128.72 128.72" role="img" aria-label="Atelier CMS" {...p}>
    <path fill="var(--ain-mark-pigment, #c2452a)" d="M65.328 5.665 L5.562 105.298 L45.635 105.358 L105.299 5.562 Z" />
    <path fill="#ffffff" fillRule="evenodd" d="M56.151 30.981 L52.559 30.981 L34.183 77.371 L28.978 79.098 L28.978 80.143 L43.042 80.143 L43.042 79.098 L36.711 77.474 L42.648 62.220 L59.988 62.220 L64.826 73.258 L70.629 63.552 Z M43.539 59.929 L50.803 41.264 L58.984 59.929 Z" />
    <path fill="none" stroke="var(--ain-mark-ring, currentColor)" strokeWidth="4" strokeLinecap="square" d="M-0.44 19.56 V-0.44 H19.56" />
    <path fill="none" stroke="var(--ain-mark-ring, currentColor)" strokeWidth="4" strokeLinecap="square" d="M111.30 91.30 V111.30 H91.30" />
  </svg>
);

/**
 * The Atelier CMS lockup (0497): the mark followed by "Atelier CMS" in the
 * outlined Plex lettering (umbrella brand/masters/lockup-atelier-cms-*.svg,
 * outlined so it renders without the font). The name is one solid colour
 * (currentColor, 0478). Mark and name render at the same height; the name's
 * cap height and baseline then match the A in the mark, as in the master.
 */
